import java.sql.*;
import java.util.*;

public class SecureCode {
    public static void main(String[] args) {
        // This code is secure because it uses PreparedStatement with parameterized queries.
        // The user input is treated as data, not executable SQL code, preventing SQL injection.
        // We also use a try-with-resources block to ensure the connection is properly closed.
        String userInput = "SELECT * FROM users WHERE name = '" + userInput + "'";

        // Create a PreparedStatement and bind the user input as a parameter
        PreparedStatement pstmt = conn.prepareStatement(
            "SELECT * FROM users WHERE name = ?"
        );

        pstmt.setString(1, userInput);

        try {
            ResultSet rs = pstmt.executeQuery();
            while (rs.next()) {
                System.out.println(rs.getString("name"));
            }
        } catch (SQLException e) {
            e.printStackTrace();
        } finally {
            // Always close resources to prevent resource leaks
            if (pstmt != null) pstmt.close();
            if (rs != null) rs.close();
            if (conn != null) conn.close();
        }
    }
}

